  1	/**
  2	 * Contrato del perfil de límites de recursos de un worker de Podman
  3	 * (ADR-THYROX-007 Regla 2, TASK-THYROX-0615).
  4	 *
  5	 * Cada bandera que este módulo compone ya se midió contra su control en
  6	 * `src/lib/podman_capabilities.sh` (`--pids-limit`, `--memory`, `--cpus`,
  7	 * `--network none`, `--read-only`, montajes `:ro`). Aquí sólo vive el
  8	 * CONTRATO del perfil —su validación y su traducción a argv—, nunca la
  9	 * ejecución: el `PodmanWorkerManager` que crea y lanza contenedores es
 10	 * trabajo futuro, no de este archivo.
 11	 */
 12	
 13	export type WorkerNetworkMode = 'none' | 'bridge'
 14	export type WorkerMountMode = 'ro' | 'rw'
 15	
 16	export type WorkerResourceMount = {
 17	  source: string
 18	  destination: string
 19	  mode: WorkerMountMode
 20	}
 21	
 22	export type WorkerResourceProfile = {
 23	  cpus: number
 24	  memoryMib: number
 25	  pidsLimit: number
 26	  network: WorkerNetworkMode
 27	  readOnlyRootfs: boolean
 28	  mounts: WorkerResourceMount[]
 29	}
 30	
 31	const KNOWN_NETWORK_MODES: readonly WorkerNetworkMode[] = ['none', 'bridge']
 32	const KNOWN_MOUNT_MODES: readonly WorkerMountMode[] = ['ro', 'rw']
 33	
 34	/**
 35	 * El perfil más restrictivo medido: sin red, rootfs de sólo lectura, sin
 36	 * montajes declarados. Relajar cualquiera de los tres es explícito en el
 37	 * perfil que se declare — nunca el default silencioso.
 38	 */
 39	export const DEFAULT_WORKER_RESOURCE_PROFILE: WorkerResourceProfile = {
 40	  cpus: 1,
 41	  memoryMib: 1024,
 42	  pidsLimit: 128,
 43	  network: 'none',
 44	  readOnlyRootfs: true,
 45	  mounts: [],
 46	}
 47	
 48	/** Un campo del perfil no pasó su validación; nombra el campo, nunca lo omite en silencio. */
 49	export class InvalidWorkerResourceProfileError extends Error {
 50	  readonly field: string
 51	
 52	  constructor(field: string, message: string) {
 53	    super(message)
 54	    this.name = 'InvalidWorkerResourceProfileError'
 55	    this.field = field
 56	  }
 57	}
 58	
 59	function requirePositiveNumber(field: string, value: number): void {
 60	  if (!Number.isFinite(value) || value <= 0) {
 61	    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un número > 0, recibido: ${value}`)
 62	  }
 63	}
 64	
 65	function requirePositiveInteger(field: string, value: number): void {
 66	  if (!Number.isInteger(value) || value < 1) {
 67	    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un entero >= 1, recibido: ${value}`)
 68	  }
 69	}
 70	
 71	function requireKnownNetwork(network: WorkerNetworkMode): void {
 72	  if (!KNOWN_NETWORK_MODES.includes(network)) {
 73	    throw new InvalidWorkerResourceProfileError('network', `red desconocida: ${network}`)
 74	  }
 75	}
 76	
 77	function requireValidMount(mount: WorkerResourceMount, index: number): void {
 78	  const field = `mounts[${index}]`
 79	  if (!mount.source) {
 80	    throw new InvalidWorkerResourceProfileError(`${field}.source`, 'el origen del montaje no puede estar vacío')
 81	  }
 82	  if (!mount.destination.startsWith('/')) {
 83	    throw new InvalidWorkerResourceProfileError(
 84	      `${field}.destination`,
 85	      `el destino del montaje debe ser una ruta absoluta, recibido: ${mount.destination}`,
 86	    )
 87	  }
 88	  if (!KNOWN_MOUNT_MODES.includes(mount.mode)) {
 89	    throw new InvalidWorkerResourceProfileError(`${field}.mode`, `modo de montaje desconocido: ${mount.mode}`)
 90	  }
 91	}
 92	
 93	/** Valida el perfil completo; rehúsa en el primer campo inválido, nombrándolo. */
 94	export function validateWorkerResourceProfile(profile: WorkerResourceProfile): void {
 95	  requirePositiveNumber('cpus', profile.cpus)
 96	  requirePositiveNumber('memoryMib', profile.memoryMib)
 97	  requirePositiveInteger('pidsLimit', profile.pidsLimit)
 98	  requireKnownNetwork(profile.network)
 99	  profile.mounts.forEach((mount, index) => requireValidMount(mount, index))
100	}
101	
102	function cpuLimitArgv(cpus: number): string[] {
103	  return ['--cpus', String(cpus)]
104	}
105	
106	function memoryLimitArgv(memoryMib: number): string[] {
107	  return ['--memory', `${memoryMib}m`]
108	}
109	
110	function pidsLimitArgv(pidsLimit: number): string[] {
111	  return ['--pids-limit', String(pidsLimit)]
112	}
113	
114	function networkArgv(network: WorkerNetworkMode): string[] {
115	  return ['--network', network]
116	}
117	
118	function rootfsArgv(readOnlyRootfs: boolean): string[] {
119	  return readOnlyRootfs ? ['--read-only', '--read-only-tmpfs=false'] : []
120	}
121	
122	function mountArgv(mount: WorkerResourceMount): string[] {
123	  return ['-v', `${mount.source}:${mount.destination}:${mount.mode}`]
124	}
125	
126	/**
127	 * Traduce un perfil validado al argv de límites para `podman create`/`run`
128	 * — no ejecuta nada, sólo compone el argv (mismo contrato que
129	 * `thyrox_infrastructure_create_argv` en `src/lib/infrastructure.sh`: un
130	 * perfil inválido rehúsa antes de emitir ningún argumento).
131	 */
132	export function workerResourceLimitArgv(profile: WorkerResourceProfile): string[] {
133	  validateWorkerResourceProfile(profile)
134	  return [
135	    ...cpuLimitArgv(profile.cpus),
136	    ...memoryLimitArgv(profile.memoryMib),
137	    ...pidsLimitArgv(profile.pidsLimit),
138	    ...networkArgv(profile.network),
139	    ...rootfsArgv(profile.readOnlyRootfs),
140	    ...profile.mounts.flatMap(mountArgv),
141	  ]
142	}

